INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Badgers', 'Step into the space suit of valiant gravity badger Captain T Bayback as he ventures into the deadly depths of deep space to save his friends, family and the universe itself from the threat of the deadly Evil Honey Badgers, aka the Hellsett. For the first time EVER a game unites the thrilling elements of Badgers and Gravity to create a stunningly presented physics-based puzzle game that will take you beyond the realms of possibility, imagination and logic to the star-dusted realm of the GRAVITY BADGERS!
