INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombball', 'Bombball is an explosive abstract sports game, available for PC, Mac, and OUYA. Bombball is designed to be spectator-friendly and easy to learn, while still requiring serious skill to master. Grab some buddies, crank the volume up, and prepare to use boosts, blasters, and bombs to get that tiebreaking goal right before the buzzer!' FROM games WHERE igdb_id = 301584 ON CONFLICT (game_id, language_code) DO NOTHING;
