INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rojiura-satsuki-chapter-heroine-sanctuary', 225654, '2013-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5rye.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rojiura Satsuki: Chapter Heroine Sanctuary', 'Rojiura Satsuki: Chapter Heroine Sanctuary is a visual novel game that features Bronze Heroines Satsuki, Riesbyfe, Sion, Ciel, and the enigmatic Heroine X (Saber) as they endeavor to ascend the twelve palaces of the Gold Heroines, inspired by the Chinese Zodiac and offering a parody of Saint Seiya. The game becomes accessible throughout the day, revealing each chapter within a stone circle that lights up with flames corresponding to each zodiac symbol. Certain chapters introduce unique mechanics, including battles reminiscent of Pokémon, which may result in a game over.' FROM games WHERE igdb_id = 225654 ON CONFLICT (game_id, language_code) DO NOTHING;
