INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bop It! Tetris', 'A handheld game licensed by The Tetris Company and produced by Hasbro, this game features two LCD screens, with the smaller one on the shorter end and the wider one going around the body of the main unit. Game-play consists of the player twisting the shorter end to position the piece projected on the smaller screen above the gap in the pieces shown on the larger, twisting the smaller screen itself to rotate the piece itself in one direction or another, then squeezing both ends together to "drop" the piece in place.
