INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie Murder', 'Charlie Murder is an action role-playing beat ''em up video game, featuring five playable characters - all members of the garage punk band Charlie Murder - who fight a demonic army raised by a former band member in an attempt to save the world from the apocalypse. Players can complete the game alone, or can team together with up to three other people, through either offline or online cooperative gameplay. With each additional player, the number of enemies that appear on screen at once increases.' FROM games WHERE igdb_id = 19914 ON CONFLICT (game_id, language_code) DO NOTHING;
