INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=GGV-T0FsxzQ', 'https://img.youtube.com/vi/GGV-T0FsxzQ/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 7543 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 7543 AND rs.code = 'CLASS_IND' AND r.code = '18' ON CONFLICT DO NOTHING;
